import hashlib

def clean_site_name(site):
    """清洗机构名中的斜杠和非法路径字符"""
    clean = re.sub(r'[/\\:*?"<>|]', '-', site).strip()
    return re.sub(r'-+', '-', clean)

def clean_filename_title(title):
    clean = "".join([c for c in title if c.isalnum() or c in (" ", "-", "_")]).strip()
    clean = re.sub(r'\s+', ' ', clean)
    return clean[:55]

def find_actual_pdf_file(target_dir, raw_filename, site, clean_title, old_id=None):
    if raw_filename and os.path.exists(os.path.join(target_dir, raw_filename)):
        return os.path.join(target_dir, raw_filename)
        
    files = [f for f in os.listdir(target_dir) if f.endswith(".pdf") and not f.startswith("__temp_")]
    
    # 优先精确匹配旧 ID 前缀，如 "[14] " 或 "[14]-"
    if old_id is not None:
        prefix = f"[{old_id}]"
        for f in files:
            if f.startswith(prefix):
                return os.path.join(target_dir, f)
                
    if raw_filename:
        base_raw = os.path.basename(raw_filename)
        if base_raw in files:
            return os.path.join(target_dir, base_raw)
            
    # 匹配标题核心词
    core_kw = clean_title[:20].lower()
    if len(core_kw) >= 5:
        for f in files:
            if core_kw in f.lower():
                return os.path.join(target_dir, f)
                
    return None

